package com.xuyuan.blog.admin.controller.misc;
import com.xuyuan.blog.admin.dto.AboutUpdateParam;import com.xuyuan.blog.admin.service.AdminAboutService;import com.xuyuan.blog.model.entity.About;import com.xuyuan.blog.common.result.R;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;
@Tag(name="后台关于我管理") @RestController @RequestMapping("/xuyuan/admin/about") @RequiredArgsConstructor public class AdminAboutController {private final AdminAboutService service;@GetMapping @Operation(summary="获取关于我") public R<About> get(){return R.ok(service.get());}@PutMapping @Operation(summary="更新关于我") public R<About> update(@Valid @RequestBody AboutUpdateParam p){return R.ok(service.update(p));}}
